stereotypeDefinition.displayFunction:
const rule = (properties["Rule"].value ?? "").trim().replace(/^optin\//, "");
const description = (properties["Description"].value ?? "").trim();
if (description) {
    return `${description} · ${rule}`;
}
const globs = (properties["Glob"].value ?? "").split("\n").map(x => x.trim()).filter(x => x.length > 0);
if (globs.length === 0) {
    return `${rule} · every file in scope`;
}
return `${rule} · ${globs[0]}${globs.length > 1 ? ` (+${globs.length - 1} more)` : ""}`;
